import logging
import os
import re

from robot.libraries import DateTime

from .option_tags import OPTION_TAG_MAPPING
from .variant_mapping_data import VARIANT_MAPPING
from ...utils.variables import get_json_env_variable_value


def should_automation_options_be_set():
    return _is_regression() and not _cm_test_information_present()


def _is_regression():
    return os.getenv("CM_USERNAME", "") == "app_cloud_regression"


def _cm_test_information_present():
    return get_json_env_variable_value("CM_TEST_INFORMATION", None) is not None


def set_automation_options_data_from_scratch(
    test_case_name, suite_source_abs_path, timeout
):
    try:
        repository_name = _get_repository_name(suite_source_abs_path)

        repository_file_path = _get_repository_file_path(
            repository_name, suite_source_abs_path
        )

        test_options = _get_automation_options_tags(repository_name=repository_name)

        automation_options = {
            "version": "1.0",
            "repository_name": repository_name,
            "repository_file_path": repository_file_path,
            "test_case_name": test_case_name,
            "test_options": test_options,
        }
        if timeout:
            automation_options["timeout"] = int(DateTime.timestr_to_secs(timeout))

        _validate_automation_options(automation_options)

        return automation_options
    except Exception as e:
        logging.error(f"Failed to create automation options. Reason: {e}")
        return None


def _validate_automation_options(automation_options):
    if (
        (not automation_options.get("repository_name"))
        or (not automation_options.get("repository_file_path"))
        or (not automation_options.get("test_case_name"))
        or (automation_options.get("test_options") is None)
    ):
        raise ValueError(
            "Automation options structure is not correct. One or more mandatory fields None"
        )


def _get_repository_name(suite_source_abs_path):
    if "/hran_ta/" in suite_source_abs_path:
        return "MN/UTE/hran_ta"
    elif "/robotlte/" in suite_source_abs_path:
        return "MN/UTE/robotlte"
    elif "/robotws/" in suite_source_abs_path:
        return "MN/UTE/robotws"
    else:
        logging.error(
            "Failed to identify repository name - not one of [ hran_ta , robotlte , robotws ]"
        )
        return None


def _get_repository_file_path(repository, suite_source_abs_path):
    try:
        if not repository:
            logging.error(
                "Failed to calculate relative path (no repository name), returning absolute path to the suite"
            )

            return None
        # remove 'MN/UTE/ from repository name
        repository_name = repository.lstrip("MN/UTE/")
        # return relative test suite file path
        return suite_source_abs_path.split(repository_name + "/")[1]
    except IndexError:
        logging.error(
            "Failed to calculate relative path (can't slice with '/'), returning absolute path to the suite"
        )

        return None


def _get_automation_options_tags(repository_name):
    cm_tags = get_json_env_variable_value("CM_TAGS", [])

    test_options = _test_options_from_tags(cm_tags)

    test_options.extend(_related_artifacts_options(cm_tags))

    test_options.extend(_get_python_related_tags(cm_tags, repository=repository_name))

    duplex_variant = _variant_from_mapping(cm_tags)

    if duplex_variant and not _duplex_variant_in_test_options(test_options):
        test_options.append(duplex_variant)

    return test_options


def _get_default_python():
    return ["PY39"]


def _get_python_related_tags(cm_tags, repository):
    python_tags = _get_python_tags_from_cm_tags(cm_tags)

    return (
        python_tags
        if (python_tags and len(python_tags) == 1)
        else _get_default_python()
    )


def _variant_from_mapping(cm_tags):
    for scope_tag, variant in VARIANT_MAPPING.items():
        if scope_tag in cm_tags:
            return variant


def _duplex_variant_in_test_options(test_options):
    variant_pattern = re.compile(r"^VARIANT_.+")
    return any((variant_pattern.match(option)) for option in test_options)


def _get_python_tags_from_cm_tags(cm_tags):
    py_pattern = re.compile(r"^PY\d\d+$")
    return [tag for tag in cm_tags if (re.compile(py_pattern).match(tag))]


def _test_options_from_tags(cm_tags):
    tag_whitelist_pattern = (
        r"(^CLOUD_.+)|(^STATE_.+)|(^CONFIGS_.+)|(^VARIANT_.+)|^(_?[^_=])+=(_?[^_=])+$"
    )
    return [tag for tag in cm_tags if re.findall(tag_whitelist_pattern, tag)]


def _related_artifacts_options(tags):
    return [OPTION_TAG_MAPPING[tag] for tag in tags if tag in OPTION_TAG_MAPPING]
